  const capabilityStatusLabels={available:'已取得',verified:'已取得',ok:'已取得',unverified:'尚未核验',checking:'检查中',empty:'未返回有效数据',timeout:'请求超时',error:'获取失败',failed:'获取失败',partial:'部分取得',not_installed:'未安装',unavailable:'未取得'};
